<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><title>Relatório Gerencial de CQ — BloodHub</title><link rel="stylesheet" href="/assets/css/quality-control-report.css"></head>
<body class="qcr-pdf"><header><img src="/assets/images/bloodhub-logo-horizontal.png" alt="BloodHub"><div><h1>Relatório Gerencial</h1><p>Controle de Qualidade de Hemocomponentes</p></div></header>
<section class="pdf-filters"><strong>Período de recebimento:</strong> <?=date('d/m/Y',strtotime($filters['from']))?> a <?=date('d/m/Y',strtotime($filters['to']))?> · <strong>Origem:</strong> <?=htmlspecialchars($filters['unit']?(array_values(array_filter($filters['units'],fn($u)=>$u['id']==$filters['unit']))[0]['name']??'—'):'Todos os processamentos')?> · <strong>Hemocomponente:</strong> <?=htmlspecialchars($filters['component']?(array_values(array_filter($filters['components'],fn($c)=>$c['id']==$filters['component']))[0]['code']??'—'):'Todos')?></section>
<section class="pdf-summary"><div><small>Registros</small><strong><?=$summary['records']?></strong></div><div><small>Conformes</small><strong><?=$summary['conforming']?></strong></div><div><small>Com NC</small><strong><?=$summary['nonconforming']?></strong></div><div><small>Processamentos</small><strong><?=$summary['units']?></strong></div></section>
<h2>Resumo por teste</h2><?php if($testSummary):?><table><thead><tr><th>Teste</th><th>Avaliados</th><th>Conformes</th><th>Fora da especificação</th></tr></thead><tbody><?php foreach($testSummary as$t):?><tr><td><?=htmlspecialchars($t['test'])?></td><td><?=$t['evaluated']?></td><td><?=$t['conforming']?></td><td><?=$t['nonconforming']?></td></tr><?php endforeach;?></tbody></table><?php endif;?>
<h2>Ocorrências fora da especificação</h2><?php if($nonconformities):?><table><thead><tr><th>Doação</th><th>Hemocomponente</th><th>Origem</th><th>Teste</th><th>Resultado</th><th>Referência</th><th>Data</th></tr></thead><tbody><?php foreach($nonconformities as$n):?><tr><td><?=htmlspecialchars($n['donation']?:'—')?></td><td><?=htmlspecialchars($n['component'])?></td><td><?=htmlspecialchars($n['origin'])?></td><td><?=htmlspecialchars($n['test'])?></td><td><?=htmlspecialchars($n['result'])?></td><td><?=htmlspecialchars($n['reference'])?></td><td><?=date('d/m/Y',strtotime($n['date']))?></td></tr><?php endforeach;?></tbody></table><?php else:?><p class="pdf-empty">Não foram identificados resultados fora da especificação no período selecionado.</p><?php endif;?>
<footer>BloodHub · Gerado em <?=date('d/m/Y H:i')?> · Documento gerencial somente leitura</footer><script>window.addEventListener('load',()=>setTimeout(()=>window.print(),150))</script></body></html>
